insert into public.words (id, language, lemma, pos, ipa_us, ipa_uk, cefr, register, forms, details, schema_version, generated_by, reviewed) values ('0203ddb5-9a93-40a9-87d6-490a47fb4ae3', 'en', 'resilient', 'adjective', 'rɪˈzɪl.jənt', 'rɪˈzɪl.i.ənt', 'C1', 'neutral', '{"inflections":[{"label":"comparative","form":"more resilient","irregular":false},{"label":"superlative","form":"most resilient","irregular":false}],"variants":[]}'::jsonb, '{"etymology_vi":"Từ tiếng Latin \"resilire\" (nhảy ngược lại): re- (lại) + salire (nhảy); vào tiếng Anh thế kỷ 17.","homonyms":[],"word_family":[{"word":"resilience","pos":"noun","note_vi":"sự kiên cường, khả năng phục hồi"},{"word":"resiliency","pos":"noun","note_vi":"như resilience, hay dùng ở Mỹ"},{"word":"resiliently","pos":"adverb","note_vi":null}],"mnemonics":[{"type":"etymology","text_vi":"re- (lại) + salire (nhảy): \"nhảy bật trở lại\" như lò xo bị nén rồi bung ra."},{"type":"image","text_vi":"Cây tre gặp bão cong rạp xuống, bão qua lại đứng thẳng: đó là resilient."}],"confusables":[{"word":"resistant","difference_vi":"resistant: chống lại, không bị tác động; resilient: bị tác động nhưng hồi phục."},{"word":"reliant","difference_vi":"Viết gần giống; reliant (on) nghĩa là phụ thuộc vào ai, cái gì."}],"confidence":{"collocations":0.92,"idioms":0.8,"mnemonics":0.75},"language_extra":null}'::jsonb, 1, 'seed', false) on conflict (language, lemma, pos) do nothing;
