insert into public.word_details (sense_id, examples, synonyms, antonyms, collocations, idioms, common_mistakes) values ('51c8ac6a-0d9c-41f6-833e-7ec0dda38a1d', '[{"sentence":"Children are often more resilient than adults think.","translation_vi":"Trẻ em thường kiên cường hơn người lớn nghĩ.","highlight":"resilient"},{"sentence":"The local economy proved remarkably resilient during the crisis.","translation_vi":"Nền kinh tế địa phương tỏ ra phục hồi rất tốt trong khủng hoảng.","highlight":"resilient"},{"sentence":"She is resilient enough to bounce back from this setback.","translation_vi":"Cô ấy đủ kiên cường để vượt qua thất bại này.","highlight":"resilient"}]'::jsonb, '[{"word":"tough","nuance_vi":"chung chung, nhấn vào sức chịu đựng hơn là khả năng hồi phục"},{"word":"tenacious","nuance_vi":"bám riết, không bỏ cuộc; nói về sự kiên trì theo đuổi"},{"word":"hardy","nuance_vi":"chịu được điều kiện khắc nghiệt; hay dùng cho cây, động vật"},{"word":"robust","nuance_vi":"chắc chắn; hay dùng cho hệ thống, nền kinh tế, vật thể"}]'::jsonb, '[{"word":"fragile"},{"word":"vulnerable"}]'::jsonb, '[{"pattern":"adverb + resilient","phrase":"remarkably / incredibly / highly resilient","example":"The species is remarkably resilient to drought."},{"pattern":"resilient + noun","phrase":"resilient economy / community / system","example":"We need a more resilient energy system."},{"pattern":"verb + resilient","phrase":"prove / remain resilient","example":"Sales remained resilient despite the recession."},{"pattern":"resilient + preposition","phrase":"resilient to / against something","example":"Coral reefs are less resilient to rising temperatures."}]'::jsonb, '[{"phrase":"bounce back","meaning_vi":"hồi phục nhanh sau thất bại, bệnh tật","register":"neutral","example":"She bounced back quickly after losing her job."},{"phrase":"roll with the punches","meaning_vi":"thích nghi, chịu đựng khó khăn mà không gục ngã","register":"informal","example":null},{"phrase":"(as) tough as old boots","meaning_vi":"cực kỳ cứng cỏi, khó bị quật ngã (Anh–Anh)","register":"informal","example":null}]'::jsonb, '[{"wrong":"resilient with stress","correct":"resilient to stress","explanation_vi":"Người Việt hay dịch \"kiên cường với\" thành \"with\"; đúng là \"to\" hoặc \"against\"."},{"wrong":"She has a lot of resilient.","correct":"She has a lot of resilience.","explanation_vi":"Sau \"a lot of\" cần danh từ resilience, không dùng tính từ."}]'::jsonb) on conflict (sense_id) do nothing;
insert into public.word_details (sense_id, examples, synonyms, antonyms, collocations, idioms, common_mistakes) values ('b7b69480-9d73-4625-9deb-3e7d4d2d2235', '[{"sentence":"This foam is light, resilient and easy to clean.","translation_vi":"Loại mút này nhẹ, đàn hồi và dễ vệ sinh.","highlight":"resilient"},{"sentence":"Rubber is a resilient material used in many shoes.","translation_vi":"Cao su là vật liệu đàn hồi được dùng trong nhiều loại giày.","highlight":"resilient"}]'::jsonb, '[{"word":"elastic","nuance_vi":"co giãn được, nhấn vào khả năng kéo dài ra"},{"word":"springy","nuance_vi":"thân mật, nảy lên khi ấn"}]'::jsonb, '[{"word":"rigid"},{"word":"brittle"}]'::jsonb, '[{"pattern":"resilient + noun","phrase":"resilient material / foam / flooring","example":"Resilient flooring is popular in kitchens."}]'::jsonb, '[]'::jsonb, '[]'::jsonb) on conflict (sense_id) do nothing;
insert into public.words (id, language, lemma, pos, ipa_us, ipa_uk, cefr, register, forms, details, schema_version, generated_by, reviewed) values ('9a06c29c-a927-47ab-a0a3-6bcc2ab9f527', 'en', 'run', 'verb', 'rʌn', 'rʌn', 'A1', 'neutral', '{"inflections":[{"label":"third_person","form":"runs","irregular":false},{"label":"past","form":"ran","irregular":true},{"label":"past_participle","form":"run","irregular":true},{"label":"present_participle","form":"running","irregular":false}],"variants":[]}'::jsonb, '{"etymology_vi":"Từ tiếng Anh cổ \"rinnan\" (chảy, chạy); nghĩa \"vận hành, điều hành\" phát triển từ hình ảnh dòng chảy liên tục.","homonyms":[],"word_family":[{"word":"runner","pos":"noun","note_vi":"người chạy"},{"word":"running","pos":"noun","note_vi":"việc chạy bộ; sự vận hành"},{"word":"runny","pos":"adjective","note_vi":"chảy nước (mũi, trứng lòng đào)"}],"mnemonics":[{"type":"sound","text_vi":"\"run\" đọc gần như \"rần\": nghe tiếng chân chạy rần rần."},{"type":"image","text_vi":"Run – ran – run: chạy một vòng rồi quay về đúng chỗ cũ, dạng V3 giống hệt V1."}],"confusables":[{"word":"ran","difference_vi":"\"ran\" là quá khứ đơn (V2); \"run\" vừa là nguyên mẫu vừa là quá khứ phân từ (V3): I have run, không phải I have ran."}],"confidence":{"collocations":0.9,"idioms":0.85,"mnemonics":0.7},"language_extra":null}'::jsonb, 1, 'seed', false) on conflict (language, lemma, pos) do nothing;
