insert into public.word_details (sense_id, examples, synonyms, antonyms, collocations, idioms, common_mistakes) values ('687fd410-3a73-4e74-bb96-61c0e417a1d2', '[{"sentence":"I run in the park every morning before work.","translation_vi":"Sáng nào tôi cũng chạy bộ trong công viên trước khi đi làm.","highlight":"run"},{"sentence":"She ran to catch the last bus home.","translation_vi":"Cô ấy chạy để bắt chuyến xe buýt cuối cùng về nhà.","highlight":"ran"},{"sentence":"The kids were running around the garden all afternoon.","translation_vi":"Bọn trẻ chạy quanh vườn cả buổi chiều.","highlight":"running"}]'::jsonb, '[{"word":"jog","nuance_vi":"chạy chậm, đều, thường để tập thể dục"},{"word":"sprint","nuance_vi":"chạy hết tốc lực trong quãng ngắn"},{"word":"dash","nuance_vi":"chạy vội đi đâu đó, thường vì gấp"}]'::jsonb, '[{"word":"walk"}]'::jsonb, '[{"pattern":"verb + adverb","phrase":"run fast / run slowly","example":"He can run fast for a big man."},{"pattern":"run + noun (khoảng cách)","phrase":"run a marathon / run 5 kilometres","example":"She ran her first marathon last year."},{"pattern":"run + preposition","phrase":"run after / run towards","example":"The dog ran after the ball."}]'::jsonb, '[{"phrase":"run for your life","meaning_vi":"chạy thục mạng để thoát thân","register":"informal","example":"When the bull broke loose, we ran for our lives."},{"phrase":"in the long run","meaning_vi":"về lâu dài","register":"neutral","example":"Exercise saves you money in the long run."}]'::jsonb, '[{"wrong":"She ran the station.","correct":"She ran to the station.","explanation_vi":"Thiếu giới từ chỉ hướng; \"run the station\" lại có nghĩa là điều hành nhà ga."}]'::jsonb) on conflict (sense_id) do nothing;
insert into public.word_details (sense_id, examples, synonyms, antonyms, collocations, idioms, common_mistakes) values ('8eb5eb3d-ffc6-43d3-8e3d-1c342d988382', '[{"sentence":"My aunt runs a small coffee shop near the market.","translation_vi":"Dì tôi điều hành một quán cà phê nhỏ gần chợ.","highlight":"runs"},{"sentence":"Who is going to run the project while you are away?","translation_vi":"Ai sẽ quản lý dự án khi anh vắng mặt?","highlight":"run"},{"sentence":"The festival is run entirely by volunteers.","translation_vi":"Lễ hội hoàn toàn do tình nguyện viên tổ chức.","highlight":"run"}]'::jsonb, '[{"word":"manage","nuance_vi":"trung tính, nhấn vào việc quản lý hằng ngày"},{"word":"operate","nuance_vi":"trang trọng hơn, hay dùng cho doanh nghiệp, dịch vụ"}]'::jsonb, '[]'::jsonb, '[{"pattern":"run + noun","phrase":"run a business / a company / a shop","example":"He has run the family business for twenty years."},{"pattern":"adverb + run","phrase":"well-run / badly run","example":"It is a well-run hotel."}]'::jsonb, '[{"phrase":"run the show","meaning_vi":"nắm quyền quyết định, cầm trịch","register":"informal","example":"Everyone knows his wife runs the show."}]'::jsonb, '[]'::jsonb) on conflict (sense_id) do nothing;
